  web.addJavascriptInterface(new Shell(),"AndroidShell");web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView view,String url){if(origin!=null&&url.equals(origin+"/android-container.html"))waitForPosInterface(120);}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())showStartupFailure("INTERFACE_LOAD");}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return origin==null||!request.getUrl().toString().startsWith(origin+"/");}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){if(origin!=null&&request.getMethod().equals("GET")&&request.getUrl().toString().startsWith(origin+"/api/")){try{HttpURLConnection c=(HttpURLConnection)new URL(request.getUrl().toString()).openConnection();c.setRequestProperty("X-Android-Access",access);String cookie=CookieManager.getInstance().getCookie(origin);if(cookie!=null)c.setRequestProperty("Cookie",cookie);int code=c.getResponseCode();String type=c.getContentType();String mime=type==null?"application/octet-stream":type.split(";")[0];Map<String,String> headers=new HashMap<>();headers.put("Cache-Control","no-store");String renewed=c.getHeaderField("Set-Cookie");if(renewed!=null)CookieManager.getInstance().setCookie(origin,renewed);InputStream stream=code<400?c.getInputStream():c.getErrorStream();return new WebResourceResponse(mime,"UTF-8",code,"Local",headers,new FilterInputStream(stream){public void close()throws IOException{super.close();c.disconnect();}});}catch(Exception error){return new WebResourceResponse("application/json","UTF-8",503,"Local",Collections.emptyMap(),new ByteArrayInputStream("{}".getBytes(StandardCharsets.UTF_8)));}}return null;}@Override public void onReceivedSslError(WebView v,android.webkit.SslErrorHandler handler,android.net.http.SslError error){handler.cancel();}});
