 private void applyImmersiveMode(){androidx.core.view.WindowInsetsControllerCompat controller=androidx.core.view.WindowCompat.getInsetsController(getWindow(),getWindow().getDecorView());controller.setSystemBarsBehavior(androidx.core.view.WindowInsetsControllerCompat.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);controller.hide(androidx.core.view.WindowInsetsCompat.Type.systemBars());}
