 @Override public void onResume(){super.onResume();NativeRuntime.peripheralForeground(true);boolean requested=resumeUpdateInstallation;resumeUpdateInstallation=false;if(requested&&getPackageManager().canRequestPackageInstalls())requestVerifiedUpdate();}
