 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)applyImmersiveMode();}
 private void waitForPosInterface(int attempts){
  if(firstFrameReady||startupProblem||isFinishing())return;
  web.evaluateJavascript("window.androidDesktopReady===true && (()=>{const w=document.getElementById('desktopApp').contentWindow;return typeof w.init==='function' && w.init.ready===true;})()",value->{
   if("true".equals(value)){web.postVisualStateCallback(0,new WebView.VisualStateCallback(){@Override public void onComplete(long requestId){if(!startupProblem&&!isFinishing()){firstFrameReady=true;web.invalidate();startupCover.revealApp();}}});}
   else if(attempts>0)web.postDelayed(()->waitForPosInterface(attempts-1),250);
   else showStartupFailure("INTERFACE_STARTUP");
  });
 }
 private void showStartupFailure(String raw){runOnUiThread(()->{
  if(startupProblem||isFinishing())return;startupProblem=true;firstFrameReady=true;startupCoverReady=true;if(startupCover!=null)startupCover.setVisibility(View.GONE);web.stopLoading();web.setVisibility(View.INVISIBLE);
  String code=raw!=null&&raw.matches("[A-Za-z0-9_]{1,60}")?raw:"STARTUP_ERROR";
  new AlertDialog.Builder(this).setTitle("El Muelle PDV no pudo abrir").setIcon(R.drawable.muelle_icon).setMessage("Tus datos se conservaron. Comparte este código para revisar el inicio: "+code).setCancelable(false).setPositiveButton("Cerrar",(dialog,index)->{finishAffinity();android.os.Process.killProcess(android.os.Process.myPid());}).show();
 });}
 private static void copyBytes(InputStream in,OutputStream out)throws IOException{byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))>0)out.write(bytes,0,n);}
 private static byte[] readBytes(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();copyBytes(in,out);return out.toByteArray();}
 private String random(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);StringBuilder value=new StringBuilder();for(byte b:bytes)value.append(String.format(Locale.ROOT,"%02x",b));return value.toString();}
 private void copyBundle(String asset,File destination)throws Exception {String[] names=getAssets().list(asset);if(names!=null&&names.length>0){destination.mkdirs();for(String name:names)copyBundle(asset+"/"+name,new File(destination,name));}else{destination.getParentFile().mkdirs();File temp=new File(destination.getPath()+".new");try(InputStream in=getAssets().open(asset);OutputStream out=new FileOutputStream(temp)){copyBytes(in,out);}if(!temp.renameTo(destination))throw new IOException("No se pudo preparar archivo");}}
 private JSONObject api(String route,String method,JSONObject body)throws Exception {HttpURLConnection connection=(HttpURLConnection)new URL(origin+route).openConnection();connection.setConnectTimeout(5000);connection.setReadTimeout(60000);connection.setRequestMethod(method);connection.setRequestProperty("X-Android-Access",access);String cookie=CookieManager.getInstance().getCookie(origin);if(cookie!=null)connection.setRequestProperty("Cookie",cookie);if(body!=null){connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");try(OutputStream out=connection.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=connection.getResponseCode();String text;try(InputStream in=code<400?connection.getInputStream():connection.getErrorStream()){text=new String(readBytes(in),StandardCharsets.UTF_8);}finally{connection.disconnect();}JSONObject result=new JSONObject(text);if(code>=400)throw new IOException(result.optString("message","La operación fue rechazada"));return result;}
 private void notice(String text){runOnUiThread(()->new AlertDialog.Builder(this).setMessage(text).setPositiveButton("Aceptar",null).show());}
 private void adminTools(){io.execute(()->{try{JSONObject session=api("/api/auth/session","GET",null);JSONObject user=session.optJSONObject("user");if(user==null||!"admin".equals(user.optString("role")))throw new SecurityException();runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Dispositivos y respaldos").setItems(new String[]{"Báscula USB OTG","Impresora USB / Bluetooth ESC/POS","Diagnóstico técnico USB","Crear respaldo cifrado","Verificar recuperación aislada","Recuperar sin sobrescribir datos"},(dialog,index)->{if(index==0)scaleDialog();else if(index==1)printerDialog();else if(index==2)scaleDiagnosticsDialog();else passwordDialog(index==3?"export":index==4?"verify":"restore");}).show());}catch(Exception error){notice("Inicia sesión como administrador para configurar equipos y respaldos.");}});}
 private void scaleDialog(){io.execute(()->{try{
  JSONArray list=api("/api/android/native","POST",new JSONObject().put("op","scaleList")).getJSONArray("value");
  String[] titles=new String[list.length()];for(int i=0;i<list.length();i++){JSONObject d=list.getJSONObject(i);titles[i]=d.optString("name","USB")+" · VID "+d.getInt("vid")+" / PID "+d.getInt("pid")+" · "+d.optString("driver");}
  runOnUiThread(()->{AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle("Báscula · seleccionar USB").setNegativeButton("Cerrar",null).setNeutralButton("Diagnóstico técnico",(dialog,index)->scaleDiagnosticsDialog());if(titles.length==0)builder.setMessage("No hay un dispositivo USB conectado. Puedes revisar el diagnóstico del último intento.");else builder.setItems(titles,(dialog,index)->{try{editScale(list.getJSONObject(index));}catch(Exception error){notice("No se pudo seleccionar el dispositivo USB");}});builder.show();});
 }catch(Exception error){notice("No se pudo consultar el puente USB: "+error.getClass().getSimpleName());}});}
 private Spinner spinner(LinearLayout layout,String title,String[] values){TextView label=new TextView(this);label.setText(title);layout.addView(label);Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));layout.addView(spinner);return spinner;}
 private void selectSpinner(Spinner spinner,String value){for(int i=0;i<spinner.getCount();i++)if(spinner.getItemAtPosition(i).toString().equals(value)){spinner.setSelection(i);return;}}
 private void editScale(JSONObject device){io.execute(()->{try{if(ScaleSerialPolicy.approvedBar9Transport(device.optInt("vid"),device.optInt("pid"))){api("/api/android/native","POST",new JSONObject().put("op","scaleOpen").put("profile",device));notice("BAR-9 · configuración automática iniciada. No necesitas introducir parámetros.");return;}JSONObject current=api("/api/android/scale","GET",null).optJSONObject("profile");if(current==null||current.optInt("vid")!=device.optInt("vid")||current.optInt("pid")!=device.optInt("pid"))current=new JSONObject();JSONObject saved=current;runOnUiThread(()->scaleProfileDialog(device,saved));}catch(Exception error){notice("No se pudo consultar el perfil USB");}});}
 private void scaleProfileDialog(JSONObject device,JSONObject saved){
  LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(24,8,24,8);TextView note=new TextView(this);note.setText("El adaptador USB no identifica el modelo de báscula. Empieza escuchando; no se enviará ningún comando. Verifica los parámetros con el manual del equipo.");form.addView(note);
  String[] drivers={"auto","ch34x","cdc","ftdi","cp210x","pl2303","hid"},protocols={"ascii-auto-safe","ascii-st-us","ascii-explicit-unit","hid-pos-scale"};
  Spinner driver=spinner(form,"Controlador detectado: "+device.optString("driver"),drivers);selectSpinner(driver,saved.optString("driver","auto"));
  Spinner protocol=spinner(form,"Formato de peso",new String[]{"Detección segura · ST/US o unidad explícita","ST/US con unidad explícita","Peso con unidad · tres tramas iguales","HID POS Scale"});for(int i=0;i<protocols.length;i++)if(protocols[i].equals(saved.optString("protocol","ascii-auto-safe")))protocol.setSelection(i);
  Spinner baud=spinner(form,"Baudios",new String[]{"9600","1200","2400","4800","19200","38400","57600","115200"});selectSpinner(baud,String.valueOf(saved.optInt("baud",9600)));
  Spinner bits=spinner(form,"Bits de datos",new String[]{"8","7","6","5"});selectSpinner(bits,String.valueOf(saved.optInt("dataBits",8)));
  Spinner parity=spinner(form,"Paridad",new String[]{"Ninguna","Impar","Par","Marca","Espacio"});parity.setSelection(Math.max(0,Math.min(4,saved.optInt("parity",0))));
  Spinner stop=spinner(form,"Bits de parada",new String[]{"1","2"});selectSpinner(stop,String.valueOf(saved.optInt("stopBits",1)));
  Spinner unit=spinner(form,"Unidad que envía la báscula",new String[]{"kg","g","lb"});selectSpinner(unit,saved.optString("unit","kg"));
  TextView limitLabel=new TextView(this);limitLabel.setText("Límite de seguridad en kg · verifica la capacidad real");form.addView(limitLabel);EditText limit=new EditText(this);limit.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);limit.setText(String.valueOf(saved.optDouble("maxKg",1000)));form.addView(limit);
  CheckBox dtr=new CheckBox(this);dtr.setText("DTR · activar sólo si lo necesita el equipo");dtr.setChecked(saved.optBoolean("dtr",false));form.addView(dtr);CheckBox rts=new CheckBox(this);rts.setText("RTS · activar sólo si lo necesita el equipo");rts.setChecked(saved.optBoolean("rts",false));form.addView(rts);
  CheckBox confirmed=new CheckBox(this);confirmed.setText("El manual de esta báscula confirma el comando P para pedir peso");confirmed.setChecked(saved.optBoolean("commandConfirmed",false));form.addView(confirmed);
  Spinner end=spinner(form,"Terminador de P · sólo con confirmación del manual",new String[]{"Sin terminador","CR","CR + LF"});String old=saved.optString("command","");end.setSelection(old.endsWith("\r\n")?2:old.endsWith("\r")?1:0);end.setEnabled(confirmed.isChecked());confirmed.setOnCheckedChangeListener((button,on)->end.setEnabled(on));
  ScrollView scroll=new ScrollView(this);scroll.addView(form);
  new AlertDialog.Builder(this).setTitle("Configurar comunicación USB").setView(scroll).setNegativeButton("Cancelar",null).setNeutralButton("Diagnóstico",(dialog,index)->scaleDiagnosticsDialog()).setPositiveButton("Guardar y conectar",(dialog,index)->io.execute(()->{try{
   String command=confirmed.isChecked()?"P"+(end.getSelectedItemPosition()==2?"\r\n":end.getSelectedItemPosition()==1?"\r":""):"";
   JSONObject value=new JSONObject().put("profileRevision",2).put("deviceId",device.getInt("deviceId")).put("driver",drivers[driver.getSelectedItemPosition()]).put("protocol",protocols[protocol.getSelectedItemPosition()]).put("baud",Integer.parseInt(baud.getSelectedItem().toString())).put("dataBits",Integer.parseInt(bits.getSelectedItem().toString())).put("parity",parity.getSelectedItemPosition()).put("stopBits",stop.getSelectedItemPosition()+1).put("unit",unit.getSelectedItem().toString()).put("maxKg",Double.parseDouble(limit.getText().toString())).put("port",0).put("dtr",dtr.isChecked()).put("rts",rts.isChecked()).put("command",command).put("commandConfirmed",confirmed.isChecked());
   JSONObject result=api("/api/android/native","POST",new JSONObject().put("op","scaleOpen").put("profile",value)).getJSONObject("value");notice(result.optString("code")+" · "+result.optString("message")+". Revisa el estado o abre Diagnóstico técnico.");
  }catch(Exception error){String message=error.getMessage();notice(message!=null&&message.startsWith("Operación nativa rechazada: scale")?message:"PROFILE_INPUT_INVALID · Revisa los parámetros USB; no se confirmó la conexión.");}})).show();
 }
 private void scaleDiagnosticsDialog(){
  LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(20,8,20,8);TextView info=new TextView(this);info.setText("Sólo datos técnicos USB. La BAR-9 se configura automáticamente y guarda un único diagnóstico privado si falla. No incluye usuarios, PIN, catálogo ni ventas; no se envía por internet. Las tramas desconocidas se ocultan.");body.addView(info);
  Button save=new Button(this);save.setText("Guardar diagnóstico técnico JSON");body.addView(save);TextView text=new TextView(this);text.setTextSize(11);text.setTextIsSelectable(true);ScrollView scroll=new ScrollView(this);scroll.addView(text);body.addView(scroll,new LinearLayout.LayoutParams(-1,360));
  java.util.concurrent.atomic.AtomicReference<JSONObject> report=new java.util.concurrent.atomic.AtomicReference<>();
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Báscula · Diagnóstico USB").setView(body).setPositiveButton("Actualizar",null).setNeutralButton("Capturar 20 s",null).setNegativeButton("Cerrar",null).create();
  java.util.function.Consumer<Boolean> refresh=start->io.execute(()->{try{JSONObject value=start?api("/api/android/native","POST",new JSONObject().put("op","scaleTraceStart")).getJSONObject("value"):api("/api/android/scale/diagnostics","GET",null);report.set(value);String formatted=value.toString(2);runOnUiThread(()->{if(dialog.isShowing()){text.setText(formatted+(start?"\n\nCaptura iniciada. Espera hasta 20 segundos y pulsa Actualizar.":""));JSONObject profile=value.optJSONObject("profile");dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setVisibility(profile!=null&&profile.optBoolean("autoBar9")?View.GONE:View.VISIBLE);}});}catch(Exception error){runOnUiThread(()->text.setText("No se pudo consultar el diagnóstico. Verifica la sesión administrativa."));}});
  dialog.setOnShowListener(ignored->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view->refresh.accept(false));dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(view->refresh.accept(true));refresh.accept(false);});
  dialog.setOnDismissListener(ignored->io.execute(()->{try{api("/api/android/native","POST",new JSONObject().put("op","scaleTraceStop"));}catch(Exception error){}}));
  save.setOnClickListener(view->{JSONObject value=report.get();if(value==null)return;saveData=android.util.Base64.encodeToString(value.toString().getBytes(StandardCharsets.UTF_8),android.util.Base64.NO_WRAP);startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"ElMuelle-USB-diagnostico.json"),43);});dialog.show();
 }

 private void printerDialog(){if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(android.Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.BLUETOOTH_CONNECT},51);notice("Después de autorizar Bluetooth, vuelve a abrir la configuración. Empareja la impresora desde Android si todavía no aparece.");return;}io.execute(()->{try{JSONArray list=api("/api/android/native","POST",new JSONObject().put("op","printerList")).getJSONArray("value");if(list.length()==0){notice("No hay impresoras USB compatibles ni dispositivos Bluetooth emparejados. La compatibilidad de impresión requiere una prueba física.");return;}String[] titles=new String[list.length()];for(int i=0;i<list.length();i++){JSONObject item=list.getJSONObject(i);titles[i]=item.optString("name","Impresora")+" · "+item.getString("transport");}runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Equipo ESC/POS (verificar modelo)").setItems(titles,(dialog,index)->io.execute(()->{try{JSONObject profile=list.getJSONObject(index);profile.put("protocol","escpos");api("/api/android/native","POST",new JSONObject().put("op","printerConfigure").put("profile",profile));notice("Equipo configurado. Esto no acredita impresión física ni compatibilidad con todos los modelos.");}catch(Exception error){notice(error.getMessage());}})).show());}catch(Exception error){notice(error.getMessage());}});}
 private void passwordDialog(String mode){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(24,8,24,8);EditText first=new EditText(this);first.setHint("Contraseña del respaldo (mínimo 6)");first.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);form.addView(first);EditText repeat=new EditText(this);if(mode.equals("export")){repeat.setHint("Repite la contraseña");repeat.setInputType(first.getInputType());form.addView(repeat);}new AlertDialog.Builder(this).setTitle(mode.equals("export")?"Crear respaldo cifrado":"Recuperación en una carpeta nueva").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Continuar",(dialog,index)->{String password=first.getText().toString();if(password.length()<6||mode.equals("export")&&!password.equals(repeat.getText().toString())){notice("Comprueba la contraseña y su confirmación.");return;}backupPassword=password;backupMode=mode;Intent intent=new Intent(mode.equals("export")?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE);if(mode.equals("export"))intent.putExtra(Intent.EXTRA_TITLE,"ElMuellePDV-Android-"+System.currentTimeMillis()+".emandroid");startActivityForResult(intent,42);}).show();}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==41){final ValueCallback<Uri[]> callback=fileCallback;fileCallback=null;if(callback==null)return;final Uri[] selected=WebChromeClient.FileChooserParams.parseResult(result,intent);if(selected==null||selected.length<1||selected.length>(fileMultiple?2:1)){callback.onReceiveValue(null);return;}io.execute(()->{try{Uri[] prepared=new Uri[selected.length];for(int i=0;i<selected.length;i++)prepared[i]=PhotoSelection.prepare(this,selected[i]);runOnUiThread(()->callback.onReceiveValue(prepared));}catch(Exception error){runOnUiThread(()->{callback.onReceiveValue(null);notice(error.getMessage()==null?"No se pudo leer la fotografía.":error.getMessage());});}});return;}if(request==42&&result==RESULT_OK&&intent!=null&&intent.getData()!=null){Uri target=intent.getData();String password=backupPassword,mode=backupMode;backupPassword=null;io.execute(()->backup(target,mode,password));}else if(request==43&&result==RESULT_OK&&intent!=null&&saveData!=null){String encoded=saveData;saveData=null;io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(intent.getData(),"w")){out.write(android.util.Base64.decode(encoded,android.util.Base64.NO_WRAP));}catch(Exception error){notice("No se pudo guardar el archivo");}});}else{backupPassword=null;saveData=null;}}
 private void backup(Uri uri,String mode,String password){File temporary=null;try{if(mode.equals("export")){JSONObject result=api("/api/android/backup/export","POST",new JSONObject().put("password",password));temporary=new File(result.getString("path"));try(InputStream in=new FileInputStream(temporary);OutputStream out=getContentResolver().openOutputStream(uri,"w")){copyBytes(in,out);}notice("Respaldo cifrado guardado. Conserva la contraseña por separado y verifica su recuperación.");}else{temporary=new File(getCacheDir(),"import-"+UUID.randomUUID()+".emandroid");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temporary)){byte[] bytes=new byte[65536];int n;long size=0;while((n=in.read(bytes))>0){size+=n;if(size>128*1024*1024)throw new IOException("Archivo demasiado grande");out.write(bytes,0,n);}}JSONObject result=api("/api/android/backup/verify","POST",new JSONObject().put("path",temporary.getPath()).put("password",password));if(mode.equals("verify")){notice("Recuperación REAL verificada en carpeta aislada: integridad, documentos, auditoría y fotografías. Los datos activos siguen intactos.");}else{String token=result.getString("token");runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Recuperación verificada").setMessage("¿Activar la copia recuperada y cerrar la aplicación? Los datos anteriores se conservarán. Vuelve a abrir el POS después.").setNegativeButton("Conservar datos actuales",null).setPositiveButton("Activar copia",(dialog,index)->io.execute(()->{try{api("/api/android/backup/activate","POST",new JSONObject().put("token",token));runOnUiThread(()->{finishAffinity();android.os.Process.killProcess(android.os.Process.myPid());});}catch(Exception error){notice(error.getMessage());}})).show());}}}catch(Exception error){notice("No se completó el respaldo o la recuperación. Comprueba contraseña e integridad. Los datos activos no se reemplazaron.");}finally{if(temporary!=null&&temporary.getParentFile().equals(getCacheDir()))temporary.delete();}}
 private void requestVerifiedUpdate(){io.execute(()->{try{Intent intent=ApkUpdateHost.verifiedIntent(MainActivity.this,api("/api/android/updates/install","POST",new JSONObject()));runOnUiThread(()->{if(!getPackageManager().canRequestPackageInstalls()){resumeUpdateInstallation=true;notice("Autoriza a El Muelle PDV para instalar actualizaciones. Al volver continuaremos con la APK verificada.");startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));return;}resumeUpdateInstallation=false;startActivity(intent);});}catch(Exception error){resumeUpdateInstallation=false;notice(error.getMessage()==null?"No se pudo verificar la actualización. No se instaló nada.":error.getMessage());}});}
 public final class Shell {
  @JavascriptInterface public String token(){return access;}
  @JavascriptInterface public void keyboard(boolean show){runOnUiThread(()->{android.view.inputmethod.InputMethodManager manager=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(manager==null)return;if(show){manager.restartInput(web);manager.showSoftInput(web,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);}else manager.hideSoftInputFromWindow(web.getWindowToken(),0);});}
  @JavascriptInterface public void installUpdate(){requestVerifiedUpdate();}
  @JavascriptInterface public String viewport(){return ((DesktopWebView)web).viewport();}
  // UI progress only, never a PIN or authorization. SharedPreferences survives
  // the random loopback port used on the next cold start of this installation.
  @JavascriptInterface public String tourProgress(String userId){if(userId==null||userId.isEmpty()||userId.length()>128)return "null";return getSharedPreferences("admin-tour-v1",MODE_PRIVATE).getString("user_"+userId,"null");}
  @JavascriptInterface public void saveTourProgress(String userId,String value){try{if(userId==null||userId.isEmpty()||userId.length()>128||value==null||value.length()>512)return;JSONObject data=new JSONObject(value);String status=data.getString("status");int chapter=data.getInt("chapter"),step=data.getInt("step");if(!Arrays.asList("offered","active","paused","dismissed","completed").contains(status)||chapter<0||chapter>100||step<0||step>200)return;JSONObject clean=new JSONObject().put("status",status).put("chapter",chapter).put("step",step);getSharedPreferences("admin-tour-v1",MODE_PRIVATE).edit().putString("user_"+userId,clean.toString()).apply();}catch(Exception ignored){}}
  @JavascriptInterface public void devices(){runOnUiThread(()->web.evaluateJavascript("(()=>{const w=document.getElementById('desktopApp')?.contentWindow||window;if(w.AndroidPeripherals)w.AndroidPeripherals.open();})()",null));}
  @JavascriptInterface public void peripheralBluetoothPermission(){io.execute(()->{try{JSONObject user=api("/api/auth/session","GET",null).optJSONObject("user");if(user==null)return;runOnUiThread(()->{if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(android.Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.BLUETOOTH_CONNECT},52);else startActivity(new Intent(android.provider.Settings.ACTION_BLUETOOTH_SETTINGS));});}catch(Exception ignored){notice("Inicia sesión para autorizar Bluetooth.");}});}
  @JavascriptInterface public void printText(String text){io.execute(()->{try{api("/api/android/print","POST",new JSONObject().put("text",text).put("requestId",UUID.randomUUID().toString()));notice("Datos enviados a la impresora configurada. Comprueba la salida en papel.");}catch(Exception error){notice("No se pudo imprimir. Configura una impresora ESC/POS compatible y comprueba su conexión.");}});}
  @JavascriptInterface public void saveDocument(String name,String mime,String encoded){if(name.length()>100||encoded.length()>24*1024*1024)return;saveData=encoded;runOnUiThread(()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name.replaceAll("[^a-zA-Z0-9._-]","_")),43));}
 }
 @Override public void onBackPressed(){web.evaluateJavascript("(()=>{const w=document.getElementById('desktopApp')?.contentWindow;return w&&typeof w.androidHandleBack==='function'?w.androidHandleBack():false})()",handled->{if(!"true".equals(handled))showCloseOptions();});}
 private void showCloseOptions(){new AlertDialog.Builder(this).setMessage("¿Cerrar la pantalla del POS? Los datos confirmados permanecerán guardados.").setNegativeButton("Volver",null).setNeutralButton("Equipos y respaldos",(dialog,index)->adminTools()).setPositiveButton("Cerrar",(dialog,index)->finish()).show();}
